import { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useForm } from 'react-hook-form';
import { zodResolver } from './zodResolver';
import { z } from 'zod';
import {
  Badge,
  Button,
  Descriptions,
  Form as AntForm,
  Input,
  Modal,
  Space,
  Table,
  Tag,
  Typography,
} from 'antd';
import type { ColumnsType } from 'antd/es/table';
import { PageContainer } from '@/components/PageContainer';
import { apiClient, ApiError } from '@/api/client';
import type {
  ApprovalRecord,
  ApprovalStatus,
  AuditRecord,
  RiskLevel,
  StateSnapshot,
} from '@/types/models';

const { Text, Paragraph } = Typography;

const approvalSchema = z.object({
  reason: z
    .string()
    .min(1, '审批必须提供理由')
    .max(240, '理由不超过 240 字'),
});

type ApprovalFormData = z.infer<typeof approvalSchema>;

const statusBadgeMap: Record<ApprovalStatus, 'processing' | 'success' | 'error' | 'default'> = {
  PENDING: 'processing',
  APPROVED: 'success',
  REJECTED: 'error',
  EXPIRED: 'default',
};

const riskColorMap: Record<RiskLevel, string> = {
  LOW: 'green',
  MEDIUM: 'gold',
  HIGH: 'orange',
  CRITICAL: 'red',
};

function useApprovals() {
  return useQuery<ApprovalRecord[], ApiError>({
    queryKey: ['approvals'],
    queryFn: () => apiClient.get<ApprovalRecord[]>('/approvals'),
  });
}

function formatStateSnapshot(snapshot: StateSnapshot): string {
  return Object.entries(snapshot)
    .map(([key, value]) => `${key}: ${value ?? 'null'}`)
    .join('\n');
}

