@RestController
public class TransferController {
  private final JdbcTemplate jdbc;
  private final ObjectMapper mapper;
  private final FineractAdapter fineract;
  private final AuditService audit;
  private final TransferStateMachine stateMachine;

  public TransferController(JdbcTemplate jdbc, ObjectMapper mapper, FineractAdapter fineract,
                            AuditService audit, TransferStateMachine stateMachine) {
    this.jdbc = jdbc;
    this.mapper = mapper;
    this.fineract = fineract;
    this.audit = audit;
    this.stateMachine = stateMachine;
  }

@PostMapping({"/api/operations/v1/transfers", "/api/customer/v1/transfers"})
  @Transactional
  public ResponseEntity<Map<String, Object>> create(
      @AuthenticationPrincipal Jwt jwt,
      @RequestHeader(value = "Idempotency-Key", required = false) String key,
      @RequestHeader(value = "X-Correlation-Id", required = false) String corrId,
      @RequestBody TransferRequest request) throws Exception {
    if (key == null || key.length() < 16 || key.length() > 128)
      throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Idempotency-Key is required");
    if (request.amount() == null || request.amount().signum() <= 0 || request.amount().scale() > 2
        || request.sourceAccountId().equals(request.destinationAccountId()))
      throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Invalid transfer");

    if (corrId == null || corrId.isBlank()) corrId = MDC.get("correlationId");

    if (jwt.getIssuer() != null && jwt.getIssuer().toString().contains("bank-customer")) {
      var clientRows = jdbc.query("SELECT fineract_client_id FROM customer_identity WHERE subject=?",
          (rs, n) -> rs.getLong(1), jwt.getSubject());
      if (clientRows.isEmpty() || fineract.clientAccounts(clientRows.get(0)).stream()
          .noneMatch(a -> String.valueOf(a.get("id")).equals(request.sourceAccountId()))) {
        throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Source account is not owned by customer");
      }
    }

String hash = sha256(mapper.writeValueAsString(request));
var existing = jdbc.query("SELECT request_hash, response_body::text, http_status FROM idempotency_record WHERE scope_key = ? AND expires_at > now()",
    (rs, n) -> Map.<String, Object>of("hash", rs.getString(1), "body", rs.getString(2), "status", rs.getInt(3)), key);
if (!existing.isEmpty()) {
  Map<String, Object> row = existing.get(0);
  if (!hash.equals(row.get("hash")))
    throw new ResponseStatusException(HttpStatus.CONFLICT, "Idempotency key body mismatch");
  return ResponseEntity.status((Integer) row.get("status")).body(mapper.readValue((String) row.get("body"), Map.class));
}

String id = UUID.randomUUID().toString();
    Map<String, Object> response = Map.<String, Object>of("transferId", id, "status", "CREATED",
        "amount", request.amount().toPlainString(), "currency", request.currency(),
        "correlationId", corrId != null ? corrId : "");
    String body = mapper.writeValueAsString(response);
    jdbc.update(
        "INSERT INTO idempotency_record(id,idempotency_key,scope_key,request_hash,status,http_status,status_code,response_headers,response_body,expires_at) "
            + "VALUES (?,?,?,?,'OK',202,202,'{}'::jsonb,?::jsonb,now() + interval '24 hours')",
        UUID.randomUUID(), key, key, hash, body);
    jdbc.update("INSERT INTO transfer_order(transfer_id,idempotency_key,source_account_id,destination_account_id,amount,currency,status,subject,correlation_id,request_hash) VALUES (?,?,?,?,?,?,?,?,?,?)",
        UUID.fromString(id), key, request.sourceAccountId(), request.destinationAccountId(),
        request.amount(), request.currency(), "CREATED", jwt.getSubject(), corrId, hash);
    // 写 CREATED 初始 state_history(无 from),保持审计链完整
    stateMachine.recordTransitionHistory(UUID.fromString(id), null,
        local.bank.channel.payments.statemachine.TransferStateMachine.Status.CREATED,
        "USER", jwt.getSubject(), null,
        "{\"idempotencyKey\":\"" + key + "\"}");
    jdbc.update("INSERT INTO outbox_event(id,aggregate_type,aggregate_id,event_type,event_version,payload,headers,status) VALUES (?,?,?,?,?,?::jsonb,?::jsonb,?)",
        UUID.randomUUID(), "Transfer", UUID.fromString(id), "transfer.status.changed", 1, body, "{}", "PENDING");

    audit.record("TRANSFER_CREATED", "USER", jwt.getSubject(), "Transfer", id, "CREATE", "SUCCESS", null, response);

return ResponseEntity.status(HttpStatus.ACCEPTED).body(response);
  }

  @GetMapping("/api/operations/v1/transfers/{transferId}")
  public Map<String, Object> get(@PathVariable UUID transferId) {
    var rows = jdbc.query(
        "SELECT transfer_id,status,amount,currency,core_reference,correlation_id FROM transfer_order WHERE transfer_id = ?",
        (rs, n) -> {
          Map<String, Object> m = new java.util.LinkedHashMap<>();
          m.put("transferId", rs.getString(1));
          m.put("status", rs.getString(2));
          m.put("amount", rs.getBigDecimal(3).toPlainString());
          m.put("currency", rs.getString(4));
          String coreRef = rs.getString(5);
          m.put("coreReference", coreRef != null ? coreRef : "");
          String corr = rs.getString(6);
          m.put("correlationId", corr != null ? corr : "");
          return m;
        }, transferId);
    if (rows.isEmpty()) throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Transfer not found");
    return rows.get(0);
  }

  public record TransferRequest(String sourceAccountId, String destinationAccountId, BigDecimal amount, String currency, String reference) {}

  private static String sha256(String input) throws Exception {
    byte[] digest = MessageDigest.getInstance("SHA-256").digest(input.getBytes(StandardCharsets.UTF_8));
    return HexFormat.of().formatHex(digest);
  }
}

package local.bank.channel;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class IdempotencyTest {

  @Test
  void sameKeyAndSameHashShouldBeIdempotent() {
    String key1 = "transfer-test-001";
    String key2 = "transfer-test-001";
    String hash1 = sha256("{\"amount\":\"100.00\"}");
    String hash2 = sha256("{\"amount\":\"100.00\"}");
    assertEquals(key1, key2);
    assertEquals(hash1, hash2);
  }

  @Test
  void sameKeyAndDifferentHashShouldConflict() {
    String key1 = "transfer-test-002";
    String key2 = "transfer-test-002";
    String hash1 = sha256("{\"amount\":\"100.00\"}");
    String hash2 = sha256("{\"amount\":\"200.00\"}");
    assertEquals(key1, key2);
    assertNotEquals(hash1, hash2);
  }

  @Test
  void coreIdempotencyKeyShouldTruncateLongKeys() {
    String longKey = "transfer-with-a-very-long-idempotency-key-that-exceeds-the-48-character-limit-of-fineract";
    String truncated = truncateCoreKey(longKey);
    assertTrue(truncated.length() <= 48);
    assertTrue(truncated.startsWith("ch-"));
  }

  @Test
  void coreIdempotencyKeyShouldNotTruncateShortKeys() {
    String shortKey = "short-key-001";
    String result = truncateCoreKey(shortKey);
    assertEquals(shortKey, result);
  }

  private String truncateCoreKey(String key) {
    if (key == null || key.length() <= 48) return key;
    try {
      byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
          .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
      return "ch-" + java.util.HexFormat.of().formatHex(digest).substring(0, 45);
    } catch (Exception e) {
      throw new RuntimeException(e);
    }
  }

  private String sha256(String input) {
    try {
      byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
          .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
      return java.util.HexFormat.of().formatHex(digest);
    } catch (Exception e) {
      throw new RuntimeException(e);
    }
  }
}
